import axios from 'axios';
import type { EmitEventRequest, GovernanceEventRecord } from './types.js';

export class GovernanceSdkClient {
  private ledgerUrl: string;

  constructor(ledgerUrl?: string) {
    this.ledgerUrl = ledgerUrl || process.env.GOVERNANCE_LEDGER_URL || 'http://localhost:3105';
  }

  async emitEvent(request: EmitEventRequest): Promise<GovernanceEventRecord> {
    try {
      const response = await axios.post(`${this.ledgerUrl}/api/v1/events`, request, { timeout: 5000 });
      return response.data as GovernanceEventRecord;
    } catch (err: any) {
      console.warn(`[GovernanceSdkClient] Failed to emit event ${request.eventType}: ${err.message}`);
      throw err;
    }
  }

  async getEvents(correlationId: string): Promise<GovernanceEventRecord[]> {
    const response = await axios.get(`${this.ledgerUrl}/api/v1/events/${correlationId}`, { timeout: 5000 });
    return response.data.events as GovernanceEventRecord[];
  }
}

export enum GovernanceEventType {
  INTENT_RECEIVED = 'security.intent.received',
  INTENT_BLOCKED = 'security.intent.blocked',
  POLICY_PRECHECK_ALLOWED = 'policy.precheck.allowed',
  POLICY_PRECHECK_DENIED = 'policy.precheck.denied',
  SIMULATION_PASSED = 'sandbox.simulation.passed',
  SIMULATION_FAILED = 'sandbox.simulation.failed',
  GENERATION_STARTED = 'generation.started',
  GENERATION_COMPLETED = 'generation.completed',
  EXECUTION_FINALIZED = 'execution.finalized',
  CAPABILITY_GRANTED = 'capability.granted',
  CAPABILITY_USED = 'capability.used',
  CAPABILITY_DENIED = 'capability.denied',
  RESOURCE_EXCEEDED = 'resource.exceeded',
  SANDBOX_TERMINATED = 'sandbox.terminated',
  EXECUTION_ATTESTATION_CREATED = 'execution.attestation.created',
  EXECUTION_REPLAY_STORED = 'execution.replay.stored'
}

export interface EmitEventRequest {
  eventType: GovernanceEventType | string;
  correlationId: string;
  actor?: string;
  service?: string;
  riskLevel?: string;
  payload: any;
}

export interface GovernanceEventRecord {
  eventId: string;
  eventType: string;
  correlationId: string;
  parentEventId: string | null;
  timestamp: string;
  actor: string;
  service: string;
  riskLevel: string | null;
  payloadHash: string;
  payload: string;
  signature: string | null;
  previousEventHash: string | null;
  currentEventHash: string;
}
